<script>
import BaseComponent from '@primevue/core/basecomponent';
import CarouselItemStyle from 'primevue/carouselitem/style';

export default {
    name: 'BaseCarouselItem',
    extends: BaseComponent,
    props: {
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        },
        value: {
            type: [String, Number],
            default: null
        }
    },
    style: CarouselItemStyle,
    provide() {
        return {
            $pcCarouselItem: this,
            $parentInstance: this
        };
    }
};
</script>
